#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    long val;
    struct Node *next;
} Node;

int main(int argc, char *argv[])
{
    Node *head = NULL;

    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }

    for (int i = 1; i < argc; ++i) {
        long v = strtol(argv[i], NULL, 10);
        Node *new_node = malloc(sizeof(Node));
        if (!new_node) {
            perror("malloc");
            return 1;
        }
        new_node->val = v;
        new_node->next = NULL;

        /* Insert while keeping the list sorted in ascending order.
           Duplicates are placed after existing equal values (stable). */
        if (!head || head->val > v) {
            new_node->next = head;
            head = new_node;
        } else {
            Node *cur = head;
            while (cur->next && cur->next->val <= v) {
                cur = cur->next;
            }
            new_node->next = cur->next;
            cur->next = new_node;
        }
    }

    /* Print the sorted list */
    Node *cur = head;
    if (!cur) {
        puts("EMPTY");
        return 0;
    }
    int first = 1;
    while (cur) {
        if (!first) {
            putchar(' ');
        }
        printf("%ld", cur->val);
        first = 0;
        cur = cur->next;
    }
    putchar('\n');
    return 0;
}
